// Se alerta SÓLO de recetas sin vector, y el resto va como informe.
//
// La distinción importa: alertar de todo lo que no está perfecto deja la
// ejecución en rojo todos los días —el catálogo sembrado ya trae cinco
// imágenes caídas— y un rojo permanente deja de significar nada. Se alerta
// de lo que cambió y hay que arreglar; se informa de lo que sólo hay que
// mirar.
//
// Recetas sin vector significa que el reindexado nocturno falló y la
// búsqueda semántica lleva horas degradada sin que nadie se entere, porque
// ese carril degrada en silencio a propósito. Eso sí es accionable.

const s = $input.first().json;
const pendientes = s.recetas - s.indexadas;

const alertas = [];
if (pendientes > 0) {
  alertas.push(`${pendientes} receta(s) sin vector: la búsqueda semántica está degradada`);
}

return [{
  json: {
    generado: new Date().toISOString(),
    catalogo: {
      culturas: s.culturas,
      recetas: s.recetas,
      indexadas: s.indexadas,
      pendientesDeIndexar: pendientes,
      imagenesRotas: s.imagenesRotas,
    },
    comunidad: {
      usuarios: s.usuarios,
      valoraciones: s.valoraciones,
      favoritos: s.favoritos,
      mediaGlobal: s.mediaGlobal,
    },
    alertas,
    estado: alertas.length ? 'ATENCION' : 'OK',
  },
}];
